/* TransferOps: demo local con persistencia exclusiva en este navegador. */
(()=>{'use strict';
const KEY='transferops_html_v1';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():`id-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const isoLocal=(d)=>{let x=new Date(d),p=n=>String(n).padStart(2,'0');return `${x.getFullYear()}-${p(x.getMonth()+1)}-${p(x.getDate())}T${p(x.getHours())}:${p(x.getMinutes())}`};
const sampleDate=(offset,h=10)=>{let d=new Date();d.setDate(d.getDate()+offset);d.setHours(h,30,0,0);return isoLocal(d)};
const seed=()=>{let a1=uid(),a2=uid(),d1=uid(),d2=uid(),v1=uid(),v2=uid(),b1=uid(),b2=uid();return {agencies:[{id:a1,name:'Caribe Travel',type:'agencia',phone:'',contact:''},{id:a2,name:'Hotel Costa Azul',type:'hotel',phone:'',contact:''}],drivers:[{id:d1,name:'Carlos Pérez',phone:'809-555-0101',active:true},{id:d2,name:'Miguel Torres',phone:'809-555-0102',active:true}],vehicles:[{id:v1,plate:'A123456',name:'Hyundai H1',capacity:8,active:true},{id:v2,plate:'B654321',name:'Toyota Hiace',capacity:12,active:true}],bookings:[{id:b1,code:'TR-0001',passenger:'John Smith',phone:'',source:'agencia',agencyId:a1,pax:4,tripType:'ida_vuelta',externalRef:'',paymentStatus:'no_indicado',requestedVehicle:'',room:'',extras:'',notes:'Ejemplo editable',legs:[{id:uid(),type:'ida',origin:'Aeropuerto PUJ',destination:'Hard Rock Punta Cana',departure:sampleDate(1,14),flight:'AA123',price:85,duration:90,driverId:d1,vehicleId:v1,status:'asignado'},{id:uid(),type:'regreso',origin:'Hard Rock Punta Cana',destination:'Aeropuerto PUJ',departure:sampleDate(5,11),flight:'AA456',price:85,duration:90,driverId:'',vehicleId:'',status:'pendiente'}]},{id:b2,code:'TR-0002',passenger:'María Rodríguez',phone:'809-555-0105',source:'directo',agencyId:'',pax:2,tripType:'solo_ida',externalRef:'',paymentStatus:'no_indicado',requestedVehicle:'',room:'',extras:'',notes:'',legs:[{id:uid(),type:'ida',origin:'Aeropuerto PUJ',destination:'Lopesan Costa Bávaro',departure:sampleDate(0,16),flight:'DL100',price:60,duration:60,driverId:d2,vehicleId:v2,status:'confirmada'}]}]}};
let db;try{let val=localStorage.getItem(KEY);db=val?JSON.parse(val):seed();if(!val)localStorage.setItem(KEY,JSON.stringify(db));}catch(e){db=seed();}
const persist=()=>{try{localStorage.setItem(KEY,JSON.stringify(db));return true}catch(e){toast('No se pudo guardar: revisa el almacenamiento del navegador');return false}};
const fmtDate=v=>v?new Date(v).toLocaleString('es-DO',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'—';
const fmtMoney=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(v)||0);
const labels={mesa:['Mesa de operaciones','Todos los traslados, prioridades y asignaciones en una sola pantalla.'],dashboard:['Dashboard','Visualiza y administra todos tus servicios desde un solo lugar.'],reservas:['Reservaciones','Registra y encuentra todas las reservas, con ida y vuelta.'],calendario:['Calendario operativo','Consulta los traslados por fecha.'],despacho:['Despacho','Asigna choferes y vehículos sin duplicar horarios.'],choferes:['Choferes','Directorio y disponibilidad de tus conductores.'],vehiculos:['Vehículos','Gestiona las unidades de tu flota.'],agencias:['Agencias y hoteles','Tus socios comerciales y las reservas que envían.']};
let current='mesa',mesaSearch='',mesaDate=isoLocal(new Date()).slice(0,10),mesaFilter='todos',mesaPage=1,mesaSelected=new Set(),search='',sourceFilter='',statusFilter='',dateFilter='',page=1,dispatchDate=isoLocal(new Date()).slice(0,10),dispatchPage=1,month=new Date(new Date().getFullYear(),new Date().getMonth(),1);const allLegs=()=>db.bookings.flatMap(b=>b.legs.map(l=>({...l,booking:b})));const legById=id=>{for(let b of db.bookings){let l=b.legs.find(x=>x.id===id);if(l)return {b,l}}return null};const nameBy=(arr,id)=>arr.find(x=>x.id===id)?.name||'Sin asignar';const vehicleName=id=>db.vehicles.find(x=>x.id===id)?.name||'Sin asignar';const tag=s=>`<span class="badge ${esc(s)}">${esc((s||'pendiente').replaceAll('_',' '))}</span>`;
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.add('hidden'),4000)}
function render(){const [title,sub]=labels[current];$('#pageTitle').textContent=title;$('#pageSubtitle').textContent=sub;$('#breadcrumb').textContent=title;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===current));document.querySelectorAll('[data-dock]').forEach(b=>{b.classList.toggle('dock-active',b.dataset.dock===current);if(b.dataset.dock===current)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});$('#content').innerHTML=({mesa,dashboard, reservas, calendario, despacho, choferes,vehiculos,agencias})[current]();bindDynamic()}
function setView(v){closeQuick();current=v;search='';sourceFilter='';statusFilter='';dateFilter='';page=1;dispatchPage=1;$('#sidebar').classList.remove('open');render()}
function stat(name,value,icon){return `<div class="stat"><span>${name}</span><b>${value}</b><i>${icon}</i></div>`}
const statusNames={pendiente:'PENDIENTE',confirmada:'CONFIRMADA',asignado:'ASIGNADA',en_camino:'EN CAMINO',pasajero_a_bordo:'A BORDO',completado:'COMPLETADA',cancelado:'CANCELADA'};
const stateClass=s=>['pendiente','confirmada','asignado','en_camino','pasajero_a_bordo','completado','cancelado'].includes(s)?s:'pendiente';
const assignedText=l=>l.driverId?nameBy(db.drivers,l.driverId):'SIN CHOFER';
const opsFlag=l=>l.arroyado?'<span class="flag-arroyado">⚠ ARROYADO</span>':'';
function changeArroyado(id){const item=legById(id);if(!item)return;item.l.arroyado=!item.l.arroyado;persist();render();if($('#quickPanel')?.classList.contains('visible'))quick(id);toast(item.l.arroyado?'Servicio marcado ARROYADO':'Marca ARROYADO retirada')}
function mesa(){
 const statuses=['pendiente','confirmada','asignado','en_camino','pasajero_a_bordo','completado','cancelado'];
 const today=isoLocal(new Date()).slice(0,10),now=Date.now();
 const rows=allLegs().filter(l=>!mesaDate||l.departure.slice(0,10)===mesaDate).sort((a,b)=>a.departure.localeCompare(b.departure));
 const active=l=>!['cancelado','completado'].includes(l.status);
 const missing=l=>active(l)&&(!l.driverId||!l.vehicleId);
 const urgent=l=>active(l)&&new Date(l.departure).getTime()>=now-30*60000&&new Date(l.departure).getTime()<=now+120*60000;
 const late=l=>active(l)&&new Date(l.departure).getTime()<now;
 const count=(fn)=>rows.filter(fn).length;
 const filtered=rows.filter(l=>{
  let b=l.booking,hay=[b.code,b.externalRef,b.passenger,b.phone,b.requestedVehicle,b.extras,l.flight,l.origin,l.destination,nameBy(db.agencies,b.agencyId),nameBy(db.drivers,l.driverId),vehicleName(l.vehicleId)].join(' ').toLowerCase();
  return hay.includes(mesaSearch.toLowerCase())&&(mesaFilter==='todos'||mesaFilter==='sin_asignar'&&missing(l)||mesaFilter==='arroyados'&&l.arroyado||mesaFilter==='urgentes'&&urgent(l)||mesaFilter==='activos'&&active(l)||mesaFilter==='completados'&&l.status==='completado');
 });
 const pages=Math.max(1,Math.ceil(filtered.length/40));mesaPage=Math.min(mesaPage,pages);let shown=filtered.slice((mesaPage-1)*40,mesaPage*40);
 const mobileCards=shown.map(l=>{let b=l.booking, isLate=late(l), isUrgent=urgent(l), isMissing=missing(l);
  const next={pendiente:'confirmada',confirmada:'asignado',asignado:'en_camino',en_camino:'pasajero_a_bordo',pasajero_a_bordo:'completado'}[l.status];
  const nextNames={confirmada:'Confirmar',asignado:'Marcar asignado',en_camino:'En camino',pasajero_a_bordo:'A bordo',completado:'Completar'};
  let driverOptions=db.drivers.filter(d=>d.active!==false||d.id===l.driverId).map(d=>`<option value="${esc(d.id)}" ${l.driverId===d.id?'selected':''}>${esc(d.name)}</option>`).join('');
  let vehicleOptions=db.vehicles.filter(v=>(v.active!==false||v.id===l.vehicleId)&&Number(v.capacity)>=b.pax).map(v=>`<option value="${esc(v.id)}" ${l.vehicleId===v.id?'selected':''}>${esc(v.name)} · ${esc(v.plate)}</option>`).join('');
  return `<article class="mobile-service state-${stateClass(l.status)} ${l.arroyado?'marked-arroyado':''} ${isLate?'service-late':isUrgent?'service-urgent':''} ${isMissing?'service-missing':''}">
    <div class="service-top"><span class="service-clock">${esc(l.departure.slice(11,16))}</span><span class="service-type ${l.type==='regreso'?'service-exit':'service-arrival'}">${l.type==='regreso'?'↗ SALIDA':'↙ LLEGADA / IDA'}</span>${isLate?'<span class="service-alert">⚠ Hora pasada</span>':isUrgent?'<span class="service-alert">⏱ Próximo</span>':''}</div>
    <div class="service-main"><div><strong class="service-name">${esc(b.passenger)}</strong><div class="service-ref">${esc(b.code)} · Res ${esc(b.externalRef||'—')}</div></div>${tag(l.status)}</div>
    <div class="mobile-driver ${l.driverId?'has-driver':'missing-driver'}">👤 CHOFER: <b>${esc(assignedText(l))}</b> ${opsFlag(l)}</div>
    <div class="service-route"><strong>${esc(l.origin)}</strong><span>↓</span><strong>${esc(l.destination)}</strong></div>
    <div class="service-chips"><span>✈ ${esc(l.flight||'Sin vuelo')}</span><span>♟ ${Number(b.pax)||0} pax</span><span>🚐 ${esc(b.requestedVehicle||'Veh. libre')}</span></div>
    <div class="service-meta">${esc(b.source==='directo'?'Cliente directo':nameBy(db.agencies,b.agencyId))} · PAY: ${esc((b.paymentStatus||'no_indicado').replaceAll('_',' '))}</div>
    ${b.extras?`<div class="service-extras">🎁 ${esc(b.extras)}</div>`:''}
    <div class="service-actions"><button class="flag-toggle ${l.arroyado?'is-marked':''}" data-arroyado="${esc(l.id)}">${l.arroyado?'✓ Quitar ARROYADO':'⚠ Marcar ARROYADO'}</button><button class="service-button assign-button" data-mesa-expand="${esc(l.id)}" aria-expanded="false">🚘 ${isMissing?'Asignar recursos':'Cambiar asignación'}</button>${next?`<button class="service-button next-button" data-mesa-next="${esc(l.id)}" data-next-status="${next}">${nextNames[next]} →</button>`:''}<button class="service-button edit-button" data-quick="${esc(l.id)}">☷</button></div>
    <div class="service-assign hidden" id="assign-${esc(l.id)}"><label>Chofer<select data-mesa-assign="driverId" data-leg="${esc(l.id)}"><option value="">Sin asignar</option>${driverOptions}</select></label><label>Vehículo<select data-mesa-assign="vehicleId" data-leg="${esc(l.id)}"><option value="">Sin asignar</option>${vehicleOptions}</select></label><label>Estado<select data-mesa-assign="status" data-leg="${esc(l.id)}">${statuses.map(v=>`<option value="${v}" ${l.status===v?'selected':''}>${v.replaceAll('_',' ')}</option>`).join('')}</select></label></div>
  </article>`
 }).join('')||'<div class="empty">No hay servicios para este filtro.</div>';
 const group=`<div class="ops-tabs">${[['todos','Todos'],['arroyados','⚠ ARROYADOS'],['sin_asignar','Sin asignar'],['urgentes','Próximos / atrasados'],['activos','Activos'],['completados','Completados']].map(([v,t])=>`<button class="ops-tab ${mesaFilter===v?'selected':''}" data-mesa-filter="${v}">${t}</button>`).join('')}</div>`;
 return `<div class="ops-stats"><div class="ops-stat"><span>Servicios en fecha</span><strong>${rows.length}</strong></div><div class="ops-stat warn"><span>Sin asignar</span><strong>${count(missing)}</strong></div><div class="ops-stat arroyados-stat" data-open-arroyados="1"><span>⚠ ARROYADOS / INCIDENCIAS</span><strong>${count(l=>l.arroyado)}</strong></div><div class="ops-stat hot"><span>Próximos 2 h / atrasados 30 min</span><strong>${count(urgent)}</strong></div><div class="ops-stat"><span>Completados</span><strong>${count(l=>l.status==='completado')}</strong></div></div>
 <div class="ops-note">Una fila = un traslado. El indicador ARROYADO se marca manualmente y aparece en su propio filtro. Ida y regreso se gestionan por separado. Las alertas se calculan con la hora del equipo, no con datos de vuelos en vivo.</div>
 <div class="section ops-board"><div class="ops-controls"><label>Fecha de trabajo<input id="mesaDate" type="date" value="${esc(mesaDate)}"></label><button class="btn btn-light btn-sm day-step" data-day-step="-1" title="Día anterior">‹</button><button class="btn btn-light btn-sm" data-mesa-today>Hoy</button><button class="btn btn-light btn-sm day-step" data-day-step="1" title="Día siguiente">›</button><button class="btn btn-light btn-sm" data-mesa-tomorrow>Mañana</button><input id="mesaSearch" class="ops-search" placeholder="Buscar pasajero, vuelo, reserva, hotel, chofer... (/)" value="${esc(mesaSearch)}"><button class="btn btn-light btn-sm ops-clear" data-clear-filters title="Limpiar todos los filtros">Limpiar filtros</button><span class="ops-count">${filtered.length} resultados</span></div>${group}
 <div class="ops-bulk"><span id="mesaSelectedCount">${mesaSelected.size} seleccionados</span><select id="mesaBulkStatus"><option value="">Cambiar estado seleccionado...</option>${statuses.map(v=>`<option value="${v}">${v.replaceAll('_',' ')}</option>`).join('')}</select><button class="btn btn-light btn-sm" id="mesaBulkApply">Aplicar</button><span class="ops-helper">N = nueva reserva · / = buscar · Esc = cerrar</span></div>
 <div class="mobile-services">${mobileCards}</div><div class="table-scroll desktop-ops-table"><table class="table ops-table"><thead><tr><th><input type="checkbox" id="mesaAll" aria-label="Seleccionar filas visibles"></th><th>Hora</th><th>Reserva / Pasajero</th><th>Ruta / Vuelo</th><th>Datos</th><th>Chofer</th><th>Vehículo</th><th>Estado</th><th>Incidencia</th><th>Editar</th></tr></thead><tbody>${shown.map(l=>{let b=l.booking;return `<tr class="ops-state-${stateClass(l.status)} ${l.arroyado?'ops-row-arroyado':''} ${late(l)?'ops-late':urgent(l)?'ops-urgent':''} ${missing(l)?'ops-unassigned':''}"><td><input type="checkbox" data-mesa-check="${esc(l.id)}" ${mesaSelected.has(l.id)?'checked':''} aria-label="Seleccionar ${esc(b.code)}"></td><td class="ops-time"><strong>${esc(l.departure.slice(11,16))}</strong><small>${l.type==='regreso'?'SALIDA':'LLEGADA / IDA'}</small>${late(l)?'<span class="ops-alert">Hora pasada</span>':urgent(l)?'<span class="ops-alert">Próximo</span>':''}</td><td><strong>${esc(b.passenger)}</strong><small>${esc(b.code)} · Res ${esc(b.externalRef||'—')}</small><small>${esc(b.source==='directo'?'Directo':nameBy(db.agencies,b.agencyId))}</small></td><td><strong>${esc(l.origin)} → ${esc(l.destination)}</strong><small>Vuelo: ${esc(l.flight||'—')}</small></td><td><strong>${Number(b.pax)||0} pax · ${esc(b.requestedVehicle||'Sin tipo')}</strong><small>PAY: ${esc((b.paymentStatus||'no_indicado').replaceAll('_',' '))}</small><small title="${esc(b.extras||'')}">${esc((b.extras||'Sin extras').slice(0,48))}</small></td><td class="ops-driver-cell ${l.driverId?'driver-assigned':'driver-missing'}"><div class="driver-identity">${l.driverId?'✓':'⚠'} ${esc(assignedText(l))}</div><select class="ops-select" data-mesa-assign="driverId" data-leg="${esc(l.id)}" aria-label="Chofer de ${esc(b.passenger)}"><option value="">⚠ Sin chofer</option>${db.drivers.filter(d=>d.active!==false||d.id===l.driverId).map(d=>`<option value="${esc(d.id)}" ${l.driverId===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select></td><td><select class="ops-select" data-mesa-assign="vehicleId" data-leg="${esc(l.id)}" aria-label="Vehículo de ${esc(b.passenger)}"><option value="">⚠ Sin vehículo</option>${db.vehicles.filter(v=>(v.active!==false||v.id===l.vehicleId)&&Number(v.capacity)>=b.pax).map(v=>`<option value="${esc(v.id)}" ${l.vehicleId===v.id?'selected':''}>${esc(v.name)} · ${esc(v.plate)}</option>`).join('')}</select></td><td class="ops-status-cell state-${stateClass(l.status)}"><span class="status-strong">${esc(statusNames[l.status]||l.status)}</span><select class="ops-select" data-mesa-assign="status" data-leg="${esc(l.id)}" aria-label="Estado de ${esc(b.passenger)}">${statuses.map(v=>`<option value="${v}" ${l.status===v?'selected':''}>${v.replaceAll('_',' ')}</option>`).join('')}</select></td><td><button class="flag-toggle ${l.arroyado?'is-marked':''}" data-arroyado="${esc(l.id)}">${l.arroyado?'⚠ ARROYADO ✓':'+ Marcar'}</button></td><td><button class="btn btn-sm btn-light ops-open" data-quick="${esc(l.id)}">Ver detalles →</button></td></tr>`}).join('')||'<tr><td colspan="10"><div class="empty">No hay servicios para este filtro.</div></td></tr>'}</tbody></table></div>
 <div class="ops-footer"><span>Mostrando ${shown.length} de ${filtered.length} · página ${mesaPage} de ${pages}</span><div><button class="btn btn-light btn-sm" data-mesa-page="-1" ${mesaPage===1?'disabled':''}>← Anterior</button><button class="btn btn-light btn-sm" data-mesa-page="1" ${mesaPage===pages?'disabled':''}>Siguiente →</button></div></div></div>`;
}
function updateMesaAssignment(el){let item=legById(el.dataset.leg);if(!item)return;let {l,b}=item,field=el.dataset.mesaAssign,value=el.value;if((field==='driverId'||field==='vehicleId')&&conflict(l,field,value)){toast('No se asignó: ya existe un traslado en ese horario.');render();return}if(field==='vehicleId'&&value&&Number(db.vehicles.find(x=>x.id===value)?.capacity||0)<b.pax){toast('No se asignó: capacidad insuficiente.');render();return}l[field]=value;if(!persist()){render();return}render();toast('Cambio guardado')}
function dashboard(){let legs=allLegs(),today=new Date().toDateString(),daily=legs.filter(l=>new Date(l.departure).toDateString()===today),up=legs.filter(l=>new Date(l.departure)>=new Date()&&l.status!=='cancelado').sort((a,b)=>a.departure.localeCompare(b.departure));return `<div class="stats">${stat('Servicios de hoy',daily.length,'▦')}${stat('Pendientes de asignar',legs.filter(l=>!l.driverId||!l.vehicleId).filter(l=>l.status!=='cancelado'&&l.status!=='completado').length,'◷')}${stat('Traslados registrados',legs.length,'↗')}${stat('Valor reservado',fmtMoney(legs.filter(l=>l.status!=='cancelado').reduce((s,l)=>s+Number(l.price||0),0)),'＄')}</div><div class="mini-row"><div class="section"><div class="section-head"><div><h2>Próximos servicios</h2><p>Traslados programados</p></div><button class="link-button" data-goto="calendario">Ver calendario →</button></div><div>${up.length?up.slice(0,6).map(l=>`<div class="detail-card"><div class="route"><strong>${esc(l.booking.passenger)}</strong><div class="secondary">${esc(l.origin)} → ${esc(l.destination)}</div><div class="secondary">${fmtDate(l.departure)}</div></div>${tag(l.status)}</div>`).join(''):'<div class="empty">No hay traslados próximos.</div>'}</div></div><div class="section"><div class="section-head"><div><h2>Resumen de operaciones</h2><p>Vista general del sistema</p></div></div><div class="section-body summary-list">${[['Reservaciones',db.bookings.length],['Clientes directos',db.bookings.filter(b=>b.source==='directo').length],['Reservas de agencias / hoteles',db.bookings.filter(b=>b.source!=='directo').length],['Choferes registrados',db.drivers.length],['Vehículos registrados',db.vehicles.length]].map(([k,v])=>`<div class="summary-item"><span>${k}</span><b>${v}</b></div>`).join('')}</div></div></div>`}
function reservas(){let rows=db.bookings.filter(b=>{let match=[b.code,b.externalRef,b.passenger,b.phone,b.requestedVehicle,b.room,b.extras,b.paymentStatus,...b.legs.flatMap(l=>[l.origin,l.destination,l.flight]),nameBy(db.agencies,b.agencyId)].join(' ').toLowerCase().includes(search.toLowerCase());return match&&(!sourceFilter||b.source===sourceFilter)&&(!statusFilter||b.legs.some(l=>l.status===statusFilter))&&(!dateFilter||b.legs.some(l=>l.departure.slice(0,10)===dateFilter))});rows.sort((a,b)=>(a.legs[0]?.departure||'').localeCompare(b.legs[0]?.departure||''));let totalPages=Math.max(1,Math.ceil(rows.length/30));page=Math.min(page,totalPages);let visible=rows.slice((page-1)*30,page*30);return `<div class="section"><div class="toolbar"><input id="searchInput" placeholder="Buscar pasajero, referencia, vuelo, vehículo, ruta o agencia..." value="${esc(search)}"><select id="sourceFilter"><option value="">Todos los orígenes</option><option value="directo" ${sourceFilter==='directo'?'selected':''}>Directos</option><option value="agencia" ${sourceFilter==='agencia'?'selected':''}>Agencias</option><option value="hotel" ${sourceFilter==='hotel'?'selected':''}>Hoteles</option></select><select id="statusFilter"><option value="">Todos los estados</option>${['pendiente','confirmada','asignado','en_camino','pasajero_a_bordo','completado','cancelado'].map(s=>`<option value="${s}" ${statusFilter===s?'selected':''}>${s.replaceAll('_',' ')}</option>`).join('')}</select></div><div class="toolbar" style="padding-top:0"><label>Fecha del servicio <input type="date" id="dateFilter" value="${esc(dateFilter)}"></label><button class="btn btn-sm btn-light" data-set-date="today">Hoy</button><button class="btn btn-sm btn-light" data-set-date="all">Todas</button><strong>${rows.length} reservas encontradas</strong></div><div class="table-scroll"><table class="table"><thead><tr><th>Reserva</th><th>Pasajero / Ref.</th><th>Origen comercial</th><th>Trayectos</th><th>Precio total</th><th>Acciones</th></tr></thead><tbody>${visible.map(b=>`<tr><td><strong>${esc(b.code)}</strong><div class="secondary">${b.tripType==='ida_vuelta'?'Ida y vuelta':'Solo ida'}</div></td><td><strong>${esc(b.passenger)}</strong><div class="secondary">${esc(b.phone||'Sin teléfono')} · Res: ${esc(b.externalRef||'—')}</div><div class="secondary">VEH: ${esc(b.requestedVehicle||'—')} · PAY: ${esc(b.paymentStatus||'no_indicado').replaceAll('_',' ')}</div><div class="secondary">Extras: ${esc(b.extras||'—')}</div></td><td>${esc(b.source==='directo'?'Directo':nameBy(db.agencies,b.agencyId))}</td><td>${b.legs.map(l=>`<div style="margin:5px 0"><strong>${l.type==='regreso'?'↩ Regreso':'↗ Ida'}</strong><div class="secondary">${fmtDate(l.departure)}</div>${tag(l.status)}</div>`).join('')}</td><td><strong>${fmtMoney(b.legs.reduce((s,l)=>s+Number(l.price),0))}</strong></td><td><div class="actions"><button class="btn btn-sm btn-light" data-edit="${esc(b.id)}">Editar</button><button class="btn btn-sm btn-light" data-delete="${esc(b.id)}">Eliminar</button></div></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty"><strong>No se encontraron reservaciones</strong>Prueba otra búsqueda o crea una nueva.</div></td></tr>'}</tbody></table></div><div class="toolbar"><button class="btn btn-sm btn-light" data-page="prev" ${page<=1?'disabled':''}>← Anterior</button><span>Página ${page} de ${totalPages} · 30 reservas por página</span><button class="btn btn-sm btn-light" data-page="next" ${page>=totalPages?'disabled':''}>Siguiente →</button></div></div>`}
function calendario(){let y=month.getFullYear(),m=month.getMonth(),first=new Date(y,m,1).getDay(),start=(first+6)%7,total=new Date(y,m+1,0).getDate(),count=Math.ceil((start+total)/7)*7,legs=allLegs(),weekday=['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'];return `<div class="section"><div class="section-head"><div><h2>Calendario mensual</h2><p>Selecciona un servicio para abrir su reservación</p></div><div class="month-bar"><button class="btn btn-light btn-sm" data-month="-1">←</button><strong>${new Intl.DateTimeFormat('es-DO',{month:'long',year:'numeric'}).format(month)}</strong><button class="btn btn-light btn-sm" data-month="1">→</button><button class="btn btn-light btn-sm" data-month="0">Hoy</button></div></div><div class="calendar">${weekday.map(w=>`<div class="day-name">${w}</div>`).join('')}${Array.from({length:count},(_,i)=>{let d=i-start+1,valid=d>0&&d<=total,date=new Date(y,m,d),key=isoLocal(date).slice(0,10),today=key===isoLocal(new Date()).slice(0,10);return `<div class="day-cell ${valid?'':'outside'} ${today?'today':''}"><span class="date">${date.getDate()}</span>${valid?legs.filter(l=>l.departure.slice(0,10)===key).map(l=>`<button class="calendar-event ${l.type==='regreso'?'return':''}" data-edit="${esc(l.booking.id)}" title="${esc(l.booking.passenger)} - ${esc(l.origin)} → ${esc(l.destination)}">${esc(l.departure.slice(11,16))} ${esc(l.booking.passenger)}</button>`).join(''):''}</div>`}).join('')}</div></div>`}
function overlap(a,b){return new Date(a.departure).getTime()<new Date(b.departure).getTime()+Number(b.duration||90)*60000&&new Date(b.departure).getTime()<new Date(a.departure).getTime()+Number(a.duration||90)*60000}
function conflict(leg,field,id){if(!id)return false;return allLegs().some(x=>x.id!==leg.id&&x[field]===id&&x.status!=='cancelado'&&x.status!=='completado'&&overlap(leg,x))}
function despacho(){let legs=allLegs().filter(l=>!dispatchDate||l.departure.slice(0,10)===dispatchDate).sort((a,b)=>a.departure.localeCompare(b.departure));let pages=Math.max(1,Math.ceil(legs.length/25));dispatchPage=Math.min(dispatchPage,pages);let visible=legs.slice((dispatchPage-1)*25,dispatchPage*25);return `<div class="notice">Asigna un chofer y un vehículo a cada trayecto. El sistema comprueba horarios solapados de acuerdo con la duración estimada. <b>No calcula tiempos reales de carretera ni sustituyen una revisión operativa.</b></div><div class="section"><div class="section-head"><h2>Agenda de despacho (${legs.length} servicios)</h2></div><div class="toolbar"><label>Fecha <input type="date" id="dispatchDate" value="${esc(dispatchDate)}"></label><button class="btn btn-sm btn-light" data-dispatch-date="today">Hoy</button><button class="btn btn-sm btn-light" data-dispatch-date="all">Todos</button></div>${visible.map(l=>`<div class="detail-card"><div class="route"><span class="details-tag">${esc(l.booking.code)} · ${l.type==='regreso'?'REGRESO':'IDA'}</span><p><strong>${esc(l.booking.passenger)}</strong> · ${l.booking.pax} pasajeros · Res: ${esc(l.booking.externalRef||'—')}</p><div class="secondary">${esc(l.origin)} → ${esc(l.destination)}</div><div class="secondary">${fmtDate(l.departure)} · ${Number(l.duration)||90} min · Vuelo ${esc(l.flight||'—')} · VEH solicitada: ${esc(l.booking.requestedVehicle||'—')}</div><div class="secondary">PAY: ${esc(l.booking.paymentStatus||'no_indicado').replaceAll('_',' ')} · Extras: ${esc(l.booking.extras||'—')} · Habitación: ${esc(l.booking.room||'—')}</div></div><div class="assign"><select class="pill-select" data-assign="driverId" data-leg="${esc(l.id)}"><option value="">Elegir chofer</option>${db.drivers.filter(d=>d.active!==false||d.id===l.driverId).map(d=>`<option value="${esc(d.id)}" ${l.driverId===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select><select class="pill-select" data-assign="vehicleId" data-leg="${esc(l.id)}"><option value="">Elegir vehículo</option>${db.vehicles.filter(v=>(v.active!==false||v.id===l.vehicleId)&&Number(v.capacity)>=l.booking.pax).map(v=>`<option value="${esc(v.id)}" ${l.vehicleId===v.id?'selected':''}>${esc(v.name)}</option>`).join('')}</select><select class="pill-select" data-assign="status" data-leg="${esc(l.id)}">${['pendiente','confirmada','asignado','en_camino','pasajero_a_bordo','completado','cancelado'].map(s=>`<option value="${s}" ${l.status===s?'selected':''}>${s.replaceAll('_',' ')}</option>`).join('')}</select></div></div>`).join('')||'<div class="empty">No hay servicios.</div>'}<div class="toolbar"><button class="btn btn-sm btn-light" data-dispatch-page="prev" ${dispatchPage<=1?'disabled':''}>← Anterior</button><span>Página ${dispatchPage} de ${pages} · 25 servicios por página</span><button class="btn btn-sm btn-light" data-dispatch-page="next" ${dispatchPage>=pages?'disabled':''}>Siguiente →</button></div><div class="small-help">Para modificar horarios, pasajeros o rutas, utiliza el módulo Reservaciones.</div></div>`}
function choferes(){return `<div class="section"><div class="section-head"><h2>Nuevo chofer</h2></div><div class="section-body"><form class="simple-form" id="driverForm"><input name="name" placeholder="Nombre completo" required maxlength="100"><input name="phone" placeholder="Teléfono"><button class="btn btn-primary">＋ Agregar chofer</button></form></div></div><div class="section"><div class="section-head"><h2>Choferes (${db.drivers.length})</h2></div><div class="table-scroll"><table class="table"><thead><tr><th>Nombre</th><th>Teléfono</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${db.drivers.map(d=>`<tr><td><strong>${esc(d.name)}</strong></td><td>${esc(d.phone)}</td><td>${tag(d.active?'asignado':'cancelado')}</td><td><button class="btn btn-light btn-sm" data-toggle-driver="${esc(d.id)}">${d.active?'Desactivar':'Activar'}</button></td></tr>`).join('')}</tbody></table></div></div>`}
function vehiculos(){return `<div class="section"><div class="section-head"><h2>Nuevo vehículo</h2></div><div class="section-body"><form class="simple-form" id="vehicleForm"><input name="name" placeholder="Modelo / unidad" required maxlength="100"><input name="plate" placeholder="Placa" required maxlength="24"><input name="capacity" type="number" min="1" max="100" placeholder="Capacidad" required><button class="btn btn-primary">＋ Agregar vehículo</button></form></div></div><div class="section"><div class="section-head"><h2>Flota (${db.vehicles.length})</h2></div><div class="table-scroll"><table class="table"><thead><tr><th>Vehículo</th><th>Placa</th><th>Capacidad</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${db.vehicles.map(v=>`<tr><td><strong>${esc(v.name)}</strong></td><td>${esc(v.plate)}</td><td>${v.capacity} pasajeros</td><td>${tag(v.active?'asignado':'cancelado')}</td><td><button class="btn btn-light btn-sm" data-toggle-vehicle="${esc(v.id)}">${v.active?'Desactivar':'Activar'}</button></td></tr>`).join('')}</tbody></table></div></div>`}
function agencias(){return `<div class="section"><div class="section-head"><h2>Agregar agencia u hotel</h2></div><div class="section-body"><form class="simple-form" id="agencyForm"><input name="name" placeholder="Nombre de agencia / hotel" maxlength="100" required><select name="type"><option value="agencia">Agencia</option><option value="hotel">Hotel</option></select><input name="phone" placeholder="Teléfono"><input name="contact" placeholder="Persona contacto"><button class="btn btn-primary">＋ Agregar</button></form></div></div><div class="section"><div class="section-head"><h2>Socios comerciales (${db.agencies.length})</h2></div><div class="table-scroll"><table class="table"><thead><tr><th>Nombre</th><th>Tipo</th><th>Contacto</th><th>Teléfono</th><th>Reservas</th><th>Acción</th></tr></thead><tbody>${db.agencies.map(a=>`<tr><td><strong>${esc(a.name)}</strong></td><td>${esc(a.type)}</td><td>${esc(a.contact||'—')}</td><td>${esc(a.phone||'—')}</td><td>${db.bookings.filter(b=>b.agencyId===a.id).length}</td><td><button class="btn btn-sm btn-light" data-delete-agency="${esc(a.id)}">Eliminar</button></td></tr>`).join('')}</tbody></table></div></div>`}
function refreshAgencyChoices(){const source=$('#sourceSelect').value,sel=$('#agencySelect'),current=sel.value;sel.innerHTML='<option value="">Sin intermediario</option>'+db.agencies.filter(a=>source==='directo'||a.type===source).map(a=>`<option value="${esc(a.id)}">${esc(a.name)}</option>`).join('');sel.value=current&&[...sel.options].some(o=>o.value===current)?current:'';sel.disabled=source==='directo';if(source==='directo')sel.value=''}
function showReturn(){let yes=$('#tripType').value==='ida_vuelta';$('#returnBox').classList.toggle('hidden',!yes);$('#bookingForm').elements.returnDeparture.required=yes}
function openModal(id){closeQuick();const f=$('#bookingForm');f.reset();f.elements.id.value='';$('#modalTitle').textContent='Nueva reservación';f.elements.departure.value=sampleDate(1,10);f.elements.returnDeparture.value=sampleDate(5,10);if(id){let b=db.bookings.find(x=>x.id===id);if(!b)return;$('#modalTitle').textContent=`Editar reservación ${b.code}`;['id','passenger','phone','source','agencyId','pax','tripType','notes','externalRef','paymentStatus','requestedVehicle','room','extras'].forEach(k=>{if(k!=='agencyId')f.elements[k].value=b[k]??''});let l=b.legs[0],r=b.legs.find(x=>x.type==='regreso');['origin','destination','departure','flight','price','duration'].forEach(k=>f.elements[k].value=l[k]??'');if(r){f.elements.returnDeparture.value=r.departure;f.elements.returnFlight.value=r.flight;f.elements.returnPrice.value=r.price;f.elements.returnDuration.value=r.duration;}refreshAgencyChoices();f.elements.agencyId.value=b.agencyId||'';}else refreshAgencyChoices();showReturn();$('#modal').classList.remove('hidden')}
function closeModal(){$('#modal').classList.add('hidden')}
function saveBooking(e){e.preventDefault();let f=e.currentTarget,v=Object.fromEntries(new FormData(f)),old=db.bookings.find(b=>b.id===v.id),isReturn=v.tripType==='ida_vuelta';if(v.source!=='directo'&&!v.agencyId)return toast('Selecciona una agencia u hotel. Primero puedes registrarlo en su módulo.');if(isReturn&&new Date(v.returnDeparture)<=new Date(v.departure))return toast('El regreso debe ser posterior a la ida.');let pax=Number(v.pax);if(!Number.isInteger(pax)||pax<1)return toast('Cantidad de pasajeros inválida');let leg=(oldLeg,type,origin,destination,departure,flight,price,duration)=>({id:oldLeg?.id||uid(),type,origin,destination,departure,flight,price:Number(price)||0,duration:Math.max(15,Number(duration)||90),driverId:oldLeg?.driverId||'',vehicleId:oldLeg?.vehicleId||'',status:oldLeg?.status||'pendiente',arroyado:oldLeg?.arroyado||false});let legs=[leg(old?.legs.find(l=>l.type==='ida'),'ida',v.origin.trim(),v.destination.trim(),v.departure,v.flight,v.price,v.duration)];if(isReturn)legs.push(leg(old?.legs.find(l=>l.type==='regreso'),'regreso',v.destination.trim(),v.origin.trim(),v.returnDeparture,v.returnFlight,v.returnPrice,v.returnDuration));if(legs.some(l=>!l.origin||!l.destination||!l.departure))return toast('Completa las rutas y fechas.');for(let l of legs){if(l.driverId&&conflict(l,'driverId',l.driverId))return toast('Conflicto de horario con el chofer asignado. Ajusta el despacho antes de guardar.');if(l.vehicleId&&conflict(l,'vehicleId',l.vehicleId))return toast('Conflicto de horario con el vehículo asignado.');if(l.vehicleId&&Number(db.vehicles.find(x=>x.id===l.vehicleId)?.capacity||0)<pax)return toast('El vehículo asignado no tiene capacidad suficiente.');}const b={id:old?.id||uid(),code:old?.code||`TR-${String(Math.max(0,...db.bookings.map(x=>Number((x.code||'').split('-').pop())||0))+1).padStart(4,'0')}`,passenger:v.passenger.trim(),phone:v.phone.trim(),source:v.source,agencyId:v.source==='directo'?'':v.agencyId,pax,tripType:v.tripType,externalRef:(v.externalRef||'').trim(),paymentStatus:v.paymentStatus||'no_indicado',requestedVehicle:(v.requestedVehicle||'').trim(),room:(v.room||'').trim(),extras:(v.extras||'').trim(),notes:v.notes.trim(),legs};if(old)db.bookings[db.bookings.indexOf(old)]=b;else db.bookings.unshift(b);persist();closeModal();setView('reservas');toast(old?'Reservación actualizada':'Reservación creada')}

function closeQuick(){const q=$('#quickPanel');if(!q)return;q.classList.remove('visible');q.setAttribute('aria-hidden','true');$('#quickBackdrop')?.classList.add('hidden')}
function quick(id){const item=legById(id);if(!item)return;const {b,l}=item;const agency=b.source==='directo'?'Cliente directo':nameBy(db.agencies,b.agencyId);
 const statuses=['pendiente','confirmada','asignado','en_camino','pasajero_a_bordo','completado','cancelado'];
 const statusLabels={pendiente:'Pendiente',confirmada:'Confirmada',asignado:'Asignado',en_camino:'En camino',pasajero_a_bordo:'Pasajero a bordo',completado:'Completado',cancelado:'Cancelado'};
 const driverOps=db.drivers.filter(x=>x.active!==false||x.id===l.driverId).map(x=>`<option value="${esc(x.id)}" ${x.id===l.driverId?'selected':''}>${esc(x.name)}</option>`).join('');
 const vehicleOps=db.vehicles.filter(x=>(x.active!==false||x.id===l.vehicleId)&&Number(x.capacity)>=Number(b.pax)).map(x=>`<option value="${esc(x.id)}" ${x.id===l.vehicleId?'selected':''}>${esc(x.name)} · ${esc(x.plate)}</option>`).join('');
 $('#quickContent').innerHTML=`<div class="quick-head"><div><span class="eyebrow">DETALLE DEL SERVICIO</span><h2>${esc(b.passenger)}</h2><div class="quick-code">${esc(b.code)} · Res ${esc(b.externalRef||'—')}</div></div><button id="quickClose" class="icon-button" aria-label="Cerrar detalle">✕</button></div>
 <div class="quick-scroll"><div class="quick-driver-banner ${l.driverId?'has-driver':'missing-driver'}"><span>CHOFER ASIGNADO</span><strong>${esc(assignedText(l))}</strong><small>${esc(l.vehicleId?vehicleName(l.vehicleId):'Vehículo sin asignar')}</small></div><button class="flag-toggle quick-flag ${l.arroyado?'is-marked':''}" data-arroyado="${esc(l.id)}">${l.arroyado?'⚠ ARROYADO — Quitar marca':'⚠ Marcar servicio ARROYADO'}</button><div class="quick-status">${tag(l.status)}<span>${esc(l.type==='regreso'?'↗ REGRESO':'↙ IDA / LLEGADA')} · ${esc(fmtDate(l.departure))}</span></div>
 <div class="quick-route"><span>ORIGEN</span><strong>${esc(l.origin)}</strong><div>↓</div><span>DESTINO</span><strong>${esc(l.destination)}</strong></div>
 <div class="quick-grid">${[['Vuelo',l.flight||'—'],['Pasajeros',b.pax],['VEH solicitada',b.requestedVehicle||'—'],['Agencia / hotel',agency],['Estado de pago',(b.paymentStatus||'no_indicado').replaceAll('_',' ')],['Precio',fmtMoney(l.price)],['Teléfono',b.phone||'—'],['Habitación',b.room||'—']].map(([k,v])=>`<div><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}</div>
 ${b.extras?`<div class="quick-note"><b>Extras</b><p>${esc(b.extras)}</p></div>`:''}${b.notes?`<div class="quick-note"><b>Observaciones</b><p>${esc(b.notes)}</p></div>`:''}
 <div class="quick-label">ASIGNACIÓN RÁPIDA</div><label class="quick-field">Chofer<select data-quick-assign="driverId" data-leg="${esc(l.id)}"><option value="">⚠ Sin chofer</option>${driverOps}</select></label><label class="quick-field">Vehículo<select data-quick-assign="vehicleId" data-leg="${esc(l.id)}"><option value="">⚠ Sin vehículo</option>${vehicleOps}</select></label><label class="quick-field">Estado<select data-quick-assign="status" data-leg="${esc(l.id)}">${statuses.map(s=>`<option value="${s}" ${s===l.status?'selected':''}>${statusLabels[s]}</option>`).join('')}</select></label>
 <div class="quick-label">ACCIONES DIRECTAS</div><div class="quick-buttons"><button class="quick-action blue" data-quick-status="confirmada" data-leg="${esc(l.id)}">✓ Confirmar</button><button class="quick-action purple" data-quick-status="en_camino" data-leg="${esc(l.id)}">➜ En camino</button><button class="quick-action amber" data-quick-status="pasajero_a_bordo" data-leg="${esc(l.id)}">♟ A bordo</button><button class="quick-action green" data-quick-status="completado" data-leg="${esc(l.id)}">✓ Completar</button></div>
 <button class="btn btn-primary full-quick-edit" data-quick-edit="${esc(b.id)}">✎ Editar datos de la reserva</button></div>`;
 $('#quickPanel').classList.add('visible');$('#quickPanel').setAttribute('aria-hidden','false');$('#quickBackdrop').classList.remove('hidden');$('#quickClose').onclick=closeQuick;$('#quickContent [data-arroyado]')?.addEventListener('click',()=>changeArroyado(l.id));
 document.querySelectorAll('[data-quick-assign]').forEach(el=>el.addEventListener('change',()=>{const field=el.dataset.quickAssign,value=el.value;if((field==='driverId'||field==='vehicleId')&&conflict(l,field,value)){toast('Conflicto: ya está ocupado en ese horario');quick(l.id);return}if(field==='vehicleId'&&value&&Number(db.vehicles.find(x=>x.id===value)?.capacity||0)<Number(b.pax)){toast('Capacidad insuficiente');quick(l.id);return}l[field]=value;persist();render();quick(l.id);toast('Asignación actualizada')}));
 document.querySelectorAll('[data-quick-status]').forEach(el=>el.addEventListener('click',()=>{let next=el.dataset.quickStatus;if(['en_camino','pasajero_a_bordo'].includes(next)&&(!l.driverId||!l.vehicleId))return toast('Asigna primero chofer y vehículo');if(l.status==='cancelado')return toast('Servicio cancelado; cambia su estado manualmente');l.status=next;persist();render();quick(l.id);toast('Estado: '+statusLabels[next])}));
 $('[data-quick-edit]').onclick=()=>openModal(b.id);
}
function exportCsv(){const head=['Código','Referencia externa','Pasajero','Teléfono','Origen comercial','Agencia / hotel','Fecha','Hora','Trayecto','Origen','Destino','Vuelo','PAX','Vehículo solicitado','Chofer','Vehículo asignado','Estado','ARROYADO','PAY','Precio USD','Extras','Observaciones'];let output=[head];for(const b of db.bookings){for(const l of b.legs){output.push([b.code,b.externalRef||'',b.passenger,b.phone,b.source,b.source==='directo'?'':nameBy(db.agencies,b.agencyId),l.departure.slice(0,10),l.departure.slice(11,16),l.type,l.origin,l.destination,l.flight,b.pax,b.requestedVehicle||'',nameBy(db.drivers,l.driverId),vehicleName(l.vehicleId),l.status,l.arroyado?'Sí':'No',b.paymentStatus,l.price,b.extras||'',b.notes||''])}}
const safe=v=>{let s=String(v??'');if(/^[=+@\-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};const csv='\uFEFF'+output.map(row=>row.map(safe).join(';')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='TransferOps-reservaciones-'+isoLocal(new Date()).slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('Archivo CSV exportado')}

function bindDynamic(){
document.querySelectorAll('#content [data-arroyado]').forEach(el=>el.addEventListener('click',()=>changeArroyado(el.dataset.arroyado)));
document.querySelectorAll('[data-open-arroyados]').forEach(el=>el.addEventListener('click',()=>{mesaFilter='arroyados';mesaPage=1;render()}));
document.querySelectorAll('[data-quick]').forEach(el=>el.addEventListener('click',()=>quick(el.dataset.quick)));
document.querySelectorAll('[data-day-step]').forEach(el=>el.addEventListener('click',()=>{let d=new Date(mesaDate+'T12:00:00');d.setDate(d.getDate()+Number(el.dataset.dayStep));mesaDate=isoLocal(d).slice(0,10);mesaPage=1;render()}));
$('[data-clear-filters]')?.addEventListener('click',()=>{mesaSearch='';mesaFilter='todos';mesaPage=1;mesaSelected.clear();render()});
$('#mesaDate')?.addEventListener('change',e=>{mesaDate=e.target.value;mesaPage=1;mesaSelected.clear();render()});
$('[data-mesa-today]')?.addEventListener('click',()=>{mesaDate=isoLocal(new Date()).slice(0,10);mesaPage=1;mesaSelected.clear();render()});
$('[data-mesa-tomorrow]')?.addEventListener('click',()=>{let d=new Date();d.setDate(d.getDate()+1);mesaDate=isoLocal(d).slice(0,10);mesaPage=1;mesaSelected.clear();render()});
$('#mesaSearch')?.addEventListener('input',e=>{let pos=e.target.selectionStart;mesaSearch=e.target.value;mesaPage=1;render();$('#mesaSearch')?.focus();$('#mesaSearch')?.setSelectionRange(pos,pos)});
document.querySelectorAll('[data-mesa-filter]').forEach(el=>el.addEventListener('click',()=>{mesaFilter=el.dataset.mesaFilter;mesaPage=1;mesaSelected.clear();render()}));
document.querySelectorAll('[data-mesa-page]').forEach(el=>el.addEventListener('click',()=>{mesaPage=Math.max(1,mesaPage+Number(el.dataset.mesaPage));render()}));
document.querySelectorAll('[data-mesa-assign]').forEach(el=>el.addEventListener('change',()=>updateMesaAssignment(el)));
document.querySelectorAll('[data-mesa-expand]').forEach(el=>el.addEventListener('click',()=>{let panel=document.getElementById('assign-'+el.dataset.mesaExpand);if(!panel)return;panel.classList.toggle('hidden');el.setAttribute('aria-expanded',String(!panel.classList.contains('hidden')))}));
document.querySelectorAll('[data-mesa-next]').forEach(el=>el.addEventListener('click',()=>{let item=legById(el.dataset.mesaNext);if(!item)return;let next=el.dataset.nextStatus;if(next==='asignado'&&(!item.l.driverId||!item.l.vehicleId))return toast('Primero asigna chofer y vehículo.');item.l.status=next;if(persist()){render();toast('Estado actualizado: '+next.replaceAll('_',' '))}}));
document.querySelectorAll('[data-mesa-check]').forEach(el=>el.addEventListener('change',()=>{el.checked?mesaSelected.add(el.dataset.mesaCheck):mesaSelected.delete(el.dataset.mesaCheck);$('#mesaSelectedCount').textContent=mesaSelected.size+' seleccionados'}));
$('#mesaAll')?.addEventListener('change',e=>{document.querySelectorAll('[data-mesa-check]').forEach(el=>{el.checked=e.target.checked;el.checked?mesaSelected.add(el.dataset.mesaCheck):mesaSelected.delete(el.dataset.mesaCheck)});$('#mesaSelectedCount').textContent=mesaSelected.size+' seleccionados'});
$('#mesaBulkApply')?.addEventListener('click',()=>{let status=$('#mesaBulkStatus').value;if(!status||!mesaSelected.size)return toast('Selecciona servicios y un estado.');let ids=[...mesaSelected];if(!confirm(`Cambiar ${ids.length} servicio(s) a ${status.replaceAll('_',' ')}?`))return;let n=0;ids.forEach(id=>{let item=legById(id);if(item){item.l.status=status;n++}});mesaSelected.clear();persist();render();toast(`${n} servicio(s) actualizados`)});

$('#dateFilter')?.addEventListener('change',e=>{dateFilter=e.target.value;page=1;render()});
document.querySelectorAll('[data-set-date]').forEach(el=>el.addEventListener('click',()=>{dateFilter=el.dataset.setDate==='today'?isoLocal(new Date()).slice(0,10):'';page=1;render()}));
document.querySelectorAll('[data-page]').forEach(el=>el.addEventListener('click',()=>{page=Math.max(1,page+(el.dataset.page==='next'?1:-1));render()}));
$('#dispatchDate')?.addEventListener('change',e=>{dispatchDate=e.target.value;dispatchPage=1;render()});
document.querySelectorAll('[data-dispatch-date]').forEach(el=>el.addEventListener('click',()=>{dispatchDate=el.dataset.dispatchDate==='today'?isoLocal(new Date()).slice(0,10):'';dispatchPage=1;render()}));
document.querySelectorAll('[data-dispatch-page]').forEach(el=>el.addEventListener('click',()=>{dispatchPage=Math.max(1,dispatchPage+(el.dataset.dispatchPage==='next'?1:-1));render()}));
const searchEl=$('#searchInput');if(searchEl)searchEl.addEventListener('input',e=>{let pos=e.target.selectionStart;search=e.target.value;page=1;render();$('#searchInput').focus();$('#searchInput').setSelectionRange(pos,pos)});$('#sourceFilter')?.addEventListener('change',e=>{sourceFilter=e.target.value;render()});$('#statusFilter')?.addEventListener('change',e=>{statusFilter=e.target.value;render()});document.querySelectorAll('[data-month]').forEach(b=>b.addEventListener('click',()=>{month=b.dataset.month==='0'?new Date(new Date().getFullYear(),new Date().getMonth(),1):new Date(month.getFullYear(),month.getMonth()+Number(b.dataset.month),1);render()}));document.querySelectorAll('[data-edit]').forEach(b=>b.addEventListener('click',()=>openModal(b.dataset.edit)));document.querySelectorAll('[data-goto]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.goto)));document.querySelectorAll('[data-delete]').forEach(b=>b.addEventListener('click',()=>{if(!confirm('¿Eliminar esta reservación y todos sus trayectos?'))return;db.bookings=db.bookings.filter(x=>x.id!==b.dataset.delete);persist();render();toast('Reservación eliminada')}));document.querySelectorAll('[data-assign]').forEach(el=>el.addEventListener('change',e=>{let item=legById(el.dataset.leg);if(!item)return;const field=el.dataset.assign,value=e.target.value,l=item.l;if((field==='driverId'||field==='vehicleId')&&conflict(l,field,value)){toast('Conflicto: el recurso ya tiene un traslado en ese horario.');render();return}if(field==='vehicleId'&&value&&Number(db.vehicles.find(x=>x.id===value)?.capacity||0)<item.b.pax){toast('Capacidad insuficiente');render();return}l[field]=value;persist();render();toast('Asignación actualizada')}));document.querySelectorAll('[data-toggle-driver]').forEach(el=>el.addEventListener('click',()=>{let d=db.drivers.find(x=>x.id===el.dataset.toggleDriver);d.active=!d.active;persist();render()}));document.querySelectorAll('[data-toggle-vehicle]').forEach(el=>el.addEventListener('click',()=>{let v=db.vehicles.find(x=>x.id===el.dataset.toggleVehicle);v.active=!v.active;persist();render()}));document.querySelectorAll('[data-delete-agency]').forEach(el=>el.addEventListener('click',()=>{let id=el.dataset.deleteAgency;if(db.bookings.some(x=>x.agencyId===id))return toast('Esta agencia/hotel tiene reservas y no se puede eliminar.');if(confirm('¿Eliminar agencia/hotel?')){db.agencies=db.agencies.filter(x=>x.id!==id);persist();render()}}));for(let [formName,coll,mapper] of [['driverForm','drivers',v=>({name:v.name.trim(),phone:v.phone.trim(),active:true})],['vehicleForm','vehicles',v=>({name:v.name.trim(),plate:v.plate.trim(),capacity:Number(v.capacity),active:true})],['agencyForm','agencies',v=>({name:v.name.trim(),type:v.type,phone:v.phone.trim(),contact:v.contact.trim()})]]){$('#'+formName)?.addEventListener('submit',e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target)),obj=mapper(v);if(!obj.name)return;db[coll].push({id:uid(),...obj});persist();render();toast('Registro agregado')})}}
document.querySelector('.mobile-dock').addEventListener('click',e=>{const b=e.target.closest('[data-dock]');if(!b)return;if(b.dataset.dock==='nuevo')openModal();else setView(b.dataset.dock)});$('#nav').addEventListener('click',e=>{let b=e.target.closest('[data-view]');if(b)setView(b.dataset.view)});$('#newBookingBtn').addEventListener('click',()=>openModal());$('#closeModal').addEventListener('click',closeModal);$('#cancelModal').addEventListener('click',closeModal);$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();closeQuick();}if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||!$('#modal').classList.contains('hidden')||e.ctrlKey||e.altKey||e.metaKey)return;if(e.key.toLowerCase()==='n'){e.preventDefault();openModal()}if(e.key==='/'){e.preventDefault();setView('mesa');$('#mesaSearch')?.focus()}});$('#tripType').addEventListener('change',showReturn);$('#sourceSelect').addEventListener('change',refreshAgencyChoices);$('#bookingForm').addEventListener('submit',saveBooking);$('#menuToggle').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#quickBackdrop').addEventListener('click',closeQuick);$('#csvBtn').addEventListener('click',exportCsv);
$('#loadDemoBtn').addEventListener('click',()=>{
 const sample=window.TRANSFEROPS_DEMO50;
 if(!sample||!Array.isArray(sample.bookings)||sample.bookings.length!==50)return toast('No se encontró el archivo de prueba.');
 const existing=new Set(db.bookings.map(b=>b.code));
 const newcomers=sample.bookings.filter(b=>!existing.has(b.code));
 if(!newcomers.length){mesaDate='2026-11-05';setView('mesa');return toast('Las 50 reservas de prueba ya están cargadas.');}
 if(!confirm(`Agregar ${newcomers.length} reservas ficticias del 5 de noviembre de 2026? No se eliminarán tus reservas existentes.`))return;
 for(const group of ['agencies','drivers','vehicles']){
   const ids=new Set(db[group].map(x=>x.id));
   db[group].push(...sample[group].filter(x=>!ids.has(x.id)));
 }
 db.bookings.push(...JSON.parse(JSON.stringify(newcomers)));
 if(!persist())return;
 mesaDate='2026-11-05';dispatchDate=mesaDate;mesaFilter='todos';mesaSearch='';mesaPage=1;
 setView('mesa');toast(`${newcomers.length} reservas de prueba agregadas, sin modificar las existentes.`);
});
$('#removeDemoBtn').addEventListener('click',()=>{
 const count=db.bookings.filter(b=>b.code.startsWith('TEST-')&&b.id.startsWith('demo-booking-')).length;
 if(!count)return toast('No hay reservas de prueba que quitar.');
 if(!confirm(`Eliminar únicamente las ${count} reservas ficticias TEST-? Las reservas reales se conservarán.`))return;
 db.bookings=db.bookings.filter(b=>!(b.code.startsWith('TEST-')&&b.id.startsWith('demo-booking-')));
 const refDrivers=new Set(db.bookings.flatMap(b=>b.legs.map(l=>l.driverId)));
 const refVehicles=new Set(db.bookings.flatMap(b=>b.legs.map(l=>l.vehicleId)));
 const refAgencies=new Set(db.bookings.map(b=>b.agencyId));
 db.drivers=db.drivers.filter(x=>!x.id.startsWith('demo-driver-')||refDrivers.has(x.id));
 db.vehicles=db.vehicles.filter(x=>!x.id.startsWith('demo-vehicle-')||refVehicles.has(x.id));
 db.agencies=db.agencies.filter(x=>!x.id.startsWith('demo-agency-')||refAgencies.has(x.id));
 persist();mesaPage=1;render();toast(`${count} reservas ficticias eliminadas.`);
});
$('#exportBtn').addEventListener('click',()=>{let blob=new Blob([JSON.stringify({exportDate:new Date().toISOString(),...db},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`transferops-copia-${isoLocal(new Date()).slice(0,10)}.json`;a.click();URL.revokeObjectURL(url);toast('Copia de seguridad descargada')});render();
})();
